principle.bad_example:
function processUser(u: any) {
  if (u) {
    if (u.isActive) {
      if (u.email) {
        return send(u.email);
      } else {
        return null;
      }
    }
  }
  return null;
}

principle.good_example:
function notifyActiveUser(user: User | null): SendResult | null {
  if (!user?.isActive || !user.email) return null;
  return send(user.email);
}
